function normalDate(value){if(typeof value!=='string')throw Error('Data inválida');const m=value.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);return J.date(m?`${m[3]}-${m[2]}-${m[1]}`:value);}
function range(start,end){J.date(start);J.date(end);if(end<start)throw Error('Fim anterior ao início');const days=[];for(let d=new Date(start+'T12:00:00Z');d.toISOString().slice(0,10)<=end;d.setUTCDate(d.getUTCDate()+1)){days.push(d.toISOString().slice(0,10));if(days.length>31)throw Error('Selecione até 31 dias');}return days;}
